(() => {
 'use strict';
 const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');
 function animate(el){el.classList.remove('fade-enter');void el.offsetWidth;if(!reduce.matches)el.classList.add('fade-enter');}
 const scenarios={
 confused:['Repeated mistakes on the same step, alongside a request for help.','The explanation may not have clicked. More of the same may not help.','Try a new example.<br>Then a smaller practice step.'],
 tired:['The student reports feeling tired and is finding it difficult to continue.','Check with the student. A pause may be more useful than another question.','Offer a short reset.<br>Then revisit the plan.'],
 ready:['Independent answers and explanations show understanding of the current step.','Check whether a fresh application is the right next challenge.','Try a fresh application.<br>Build on what clicked.']};
 function selectTab(button,selector){document.querySelectorAll(selector).forEach(b=>{const chosen=b===button;b.setAttribute('aria-selected',String(chosen));b.tabIndex=chosen?0:-1;b.classList.toggle('selected',chosen);});}
 document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>{selectTab(b,'[data-scenario]');const data=scenarios[b.dataset.scenario];document.querySelector('#signal-copy').textContent=data[0];document.querySelector('#context-copy').textContent=data[1];document.querySelector('#action-copy').innerHTML=data[2];document.querySelector('#scenario-panel').setAttribute('aria-labelledby',b.id);animate(document.querySelector('#scenario-panel'));}));
 const teams={
 plan:{tag:'THE COORDINATOR',title:'A clearer answer to<br>“aaj kya padhoon?”',description:'A starting assessment, the syllabus, available study time and daily learning evidence come together in an individual plan. As understanding changes, the plan can change too.',rows:[['Revisit the tricky concept','A different explanation','LEARN'],['Try a focused set','Apply it independently','PRACTISE'],['Come back to it','Check what you remember','REVISE']],bottom:'The planner coordinates. Specialist agents deliver the learning activities.'},
 learn:{tag:'THE EXPLANATION',title:'Samajhne ka tareeka<br>badal sakta hai.',description:'Lessons combine content blocks, examples, language and depth around the learner. When an adjustment is approved, the explanation or pace can change during the session.',rows:[['Build the idea','Start with context','CONCEPT'],['Make it relatable','A different example or visual','EXPLAIN'],['Check the next step','Use the response to inform the plan','ADAPT']],bottom:'English or Hinglish. Basic or advanced depth. Choices informed by the learning journey.'},
 practice:{tag:'THE PRACTICE AGENT',title:'Jahan gap hai,<br>wahin practice.',description:'The Practice Agent recommends what to practise and which mode to use based on demonstrated understanding and gaps. The learning planner decides when it fits.',rows:[['Locate the difficulty','Use the evidence from learning','IDENTIFY'],['Choose the practice','Match the topic and mode','RECOMMEND'],['Feed the result back','Let the planner choose what follows','UPDATE']],bottom:'A recommendation is not an automatic assignment. The planner coordinates the next step.'},
 revision:{tag:'THE REVISION AGENT',title:'Yaad bhi rahe.<br>Samajh bhi aaye.',description:'Revisit ideas in short, approximately 30-second clips, or become the teacher in “Teach Me Something”. The AI asks questions to explore understanding and surface gaps.',rows:[['Byte-size learning','Quick concept refreshers','REVISIT'],['Teach Me Something','Explain the topic to the AI','EXPLAIN'],['Close the gap','A prompt now, or a new planned activity','FOLLOW UP']],bottom:'Smaller gaps can be explored in-session. Larger ones inform practice or relearning.'}};
 document.querySelectorAll('[data-team]').forEach(b=>b.addEventListener('click',()=>{selectTab(b,'[data-team]');const t=teams[b.dataset.team],panel=document.querySelector('#team-panel');panel.setAttribute('aria-labelledby',b.id);panel.querySelector('.pill').textContent=t.tag;document.querySelector('#team-title').innerHTML=t.title;document.querySelector('#team-desc').textContent=t.description;document.querySelector('#team-bottom').textContent=t.bottom;document.querySelector('#team-example').innerHTML='<div class="schedule-title"><span>YOUR NEXT LEARNING STEPS</span><span>Example</span></div>'+t.rows.map((r,i)=>`<div><span class="schedule-icon">0${i+1}</span><span><b>${r[0]}</b><small>${r[1]}</small></span><span class="schedule-type">${r[2]}</span></div>`).join('');animate(panel);}));
 document.querySelectorAll('[role=tablist]').forEach(list=>list.addEventListener('keydown',e=>{const tabs=[...list.querySelectorAll('[role=tab]')];let i=tabs.indexOf(document.activeElement);if(i<0)return;const keys=['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'];if(!keys.includes(e.key))return;e.preventDefault();i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)+tabs.length)%tabs.length;tabs[i].focus();tabs[i].click();}));
 const config=window.INTO3_CONFIG||{};let checkoutUrl=null;
 const whatsapp=String(config.whatsappNumber||'').replace(/[^0-9]/g,'');
 if(/^[1-9][0-9]{7,14}$/.test(whatsapp)){
  const url='https://wa.me/'+whatsapp+'?text='+encodeURIComponent('Hi Into3, I would like to know more about the founding-family offer for my child.');
  document.querySelectorAll('[data-whatsapp]').forEach(a=>{a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.innerHTML='Chat with us on WhatsApp <span aria-hidden="true">↗</span>';});
  document.querySelectorAll('[data-whatsapp-note]').forEach(p=>p.textContent='Opens WhatsApp. A message is only sent when you choose to send it.');
  document.querySelectorAll('[data-contact-footer]').forEach(a=>{a.href=url;a.textContent='Contact us on WhatsApp';a.target='_blank';a.rel='noopener noreferrer';});
  const floating=document.createElement('a');floating.href=url;floating.target='_blank';floating.rel='noopener noreferrer';floating.className='button floating-contact';floating.setAttribute('aria-label','Contact Into3 on WhatsApp');floating.textContent='WhatsApp us ↗';document.body.append(floating);
 }

 try{const u=new URL(config.checkoutUrl);if(u.protocol==='https:'&&['rzp.io','razorpay.com','pages.razorpay.com','payments.cashfree.com','www.cashfree.com'].includes(u.hostname)&&!u.username&&!u.password&&config.termsConfirmed&&config.accessWindow&&config.refundTerms)checkoutUrl=u.href;}catch{}
 const reservation=document.querySelector('#reservation-dialog');
 if(checkoutUrl){const link=document.querySelector('#checkout-link');link.href=checkoutUrl;link.hidden=false;document.querySelector('#checkout-status').textContent=`Access: ${config.accessWindow}. Refund terms: ${config.refundTerms}`;const note=document.querySelector('#payment-note');if(note)note.textContent=`Access: ${config.accessWindow}. View terms before secure checkout.`;reservation.querySelector('.dialog-footnote').textContent='Your reservation is confirmed only after successful payment on the payment provider’s page.';}
 document.querySelectorAll('[data-reserve]').forEach(b=>b.addEventListener('click',()=>{location.href='checkout.html';}));
 document.querySelectorAll('dialog').forEach(d=>{d.querySelectorAll('.dialog-close,.dialog-dismiss').forEach(b=>b.addEventListener('click',()=>d.close()));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
 const policies={privacy:['Privacy on this page','This page does not collect registration details, student answers or health information. Meta Pixel is used on marketing pages to measure visits and advertising performance. Payment and administrator pages do not load this pixel. Fonts are requested from Google Fonts; images are served with the page. Hosting providers may process ordinary technical request logs.','Before reservations open, the checkout will identify the payment provider and explain the information required to process the reservation. The full student-product privacy notice will be provided before onboarding.'],terms:['Founding offer terms','The founding offer is a ₹100 reservation, one introductory month when access begins, then ₹1,399 per month for six paid months. The reservation is credited toward the first paid bill, making that bill ₹1,299. The planned price thereafter is ₹1,499/month.','Pre-launch: December 2026–January 2027 planned launch; Phase 1 capacity is 5,000 students. Access is not immediate. Reservations are open on the secure checkout page, which shows the reservation, cancellation and refund terms before payment. A place is reserved only after a successful payment; opening this page does not reserve one.']};
 document.querySelectorAll('[data-policy]').forEach(b=>b.addEventListener('click',()=>{const data=policies[b.dataset.policy];document.querySelector('#policy-title').textContent=data[0];const content=document.querySelector('#policy-content');content.replaceChildren(...data.slice(1).map(t=>{const p=document.createElement('p');p.textContent=t;return p;}));document.querySelector('#policy-dialog').showModal();}));
 if('IntersectionObserver' in window){document.documentElement.classList.add('js');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));}
 let queued=false;function progress(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.transform=`scaleX(${max>0?Math.min(1,Math.max(0,scrollY/max)):0})`;queued=false;}window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(progress);}},{passive:true});progress();
})();
